package com.procurement.goodsreceipt.mapper;import com.procurement.goodsreceipt.dto.response.*;import com.procurement.goodsreceipt.entity.*;import org.springframework.stereotype.Component;@Component public class GrnMapper{public GrnResponse grn(GoodsReceiptNote e){return new GrnResponse(e.getId(),e.getGrnNumber(),e.getPurchaseOrder().getId(),e.getPurchaseOrder().getPoNumber(),e.getVendor().getId(),e.getVendor().getVendorName(),e.getWarehouse().getId(),e.getWarehouse().getWarehouseName(),e.getReceiptDate(),e.getStatus(),e.getRemarks());}public GrnLineResponse line(GoodsReceiptLine e){return new GrnLineResponse(e.getId(),e.getGoodsReceiptNote().getId(),e.getPurchaseOrderLine().getId(),e.getProduct().getId(),e.getProduct().getProductName(),e.getOrderedQuantity(),e.getReceivedQuantity(),e.getAcceptedQuantity(),e.getRejectedQuantity(),e.getDamagedQuantity(),e.getRemainingQuantity());}}
